import pickle, random
from collections import defaultdict, Counter

d4 = pickle.load(open('/tmp/dev4.pkl','rb'))
d5 = pickle.load(open('/tmp/dev5.pkl','rb'))
qs = d4 + d5
random.seed(7)

def make_queues(q):
    pv = defaultdict(list)
    for s in q['samples']:
        pv[s['variant']].append(s)
    for v in pv:
        random.shuffle(pv[v])
    return pv

def sum_per_variant_max(collected):
    best = defaultdict(lambda: -1e9)
    for s in collected:
        key=(s['answer'], s['variant'])
        if s['score']>best[key]:
            best[key]=s['score']
    sums=defaultdict(float)
    variant_count=defaultdict(set)
    for (a,v), sc in best.items():
        sums[a]+=sc
        variant_count[a].add(v)
    if not sums:
        return None, None, 0, sums
    ranked = sorted(sums.items(), key=lambda kv: -kv[1])
    top_a, top_s = ranked[0]
    second_s = ranked[1][1] if len(ranked)>1 else -1e9
    return top_a, top_s-second_s, len(variant_count[top_a]), sums

def run(qs, phase1_v, phase2_v, gap_thresh, nvar_thresh, max_cap, unanimous_stop=True):
    results=[]
    for q in qs:
        pv = make_queues(q)
        collected=[]
        idx=defaultdict(int)
        cost=0
        for v in phase1_v:
            if idx[v]<len(pv[v]):
                collected.append(pv[v][idx[v]]); idx[v]+=1; cost+=1
        answers=set(s['answer'] for s in collected)
        stopped=False
        if unanimous_stop and len(answers)==1:
            ans=collected[0]['answer']; stopped=True
        if not stopped:
            for v in phase2_v:
                if idx[v]<len(pv[v]):
                    collected.append(pv[v][idx[v]]); idx[v]+=1; cost+=1
            top_a, gap, nvar, sums = sum_per_variant_max(collected)
            if nvar>=nvar_thresh and gap>gap_thresh:
                ans=top_a; stopped=True
        if not stopped:
            order=[0,1,2,3,4]
            rv=0
            while cost<max_cap:
                v=order[rv%5]; rv+=1
                if idx[v]>=len(pv[v]):
                    if all(idx[vv]>=len(pv[vv]) for vv in range(5)):
                        break
                    continue
                collected.append(pv[v][idx[v]]); idx[v]+=1; cost+=1
                top_a, gap, nvar, sums = sum_per_variant_max(collected)
                if nvar>=nvar_thresh and gap>gap_thresh:
                    ans=top_a; stopped=True; break
            if not stopped:
                ans=top_a
        results.append((ans==q['correct_answer'], cost))
    accs=[r[0] for r in results]; costs=[r[1] for r in results]
    return sum(accs)/len(accs), sum(costs)/len(costs), max(costs)

# grid search
best=[]
for gap_thresh in [0.5, 0.8, 1.0, 1.5, 2.0]:
    for nvar_thresh in [2,3]:
        for max_cap in [8,10,12,15]:
            acc, avgcost, mx = run(qs, [0,1,2],[3,4], gap_thresh, nvar_thresh, max_cap)
            best.append((acc, avgcost, mx, gap_thresh, nvar_thresh, max_cap))

best.sort(key=lambda x: (-x[0], x[1]))
for row in best[:20]:
    print(row)
